import React from 'react'
import { useDispatch } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';

interface IContextProps {
	trackEvent: ( event: string, properties?: Record<string, unknown> ) => void;
}

const AnalyticsContext = React.createContext<IContextProps>( {
	trackEvent: () => null,
} )


export const useAnalyticsContext = () => React.useContext( AnalyticsContext )

interface IAnalyticsProviderProps {
	children: React.ReactNode;
	version: string;
}

export const AnalyticsContextProvider: React.FC<IAnalyticsProviderProps> = React.memo( ( { children, version } ) => {

	const dispatch = useDispatch()

	const trackEvent = React.useCallback( ( eventName: string, properties: Record<string, unknown> = {} ) => {
		dispatch( trackPageViews( null, {
			eventName,
			track_type: 'event',
			eventProperty: {
				...properties,
				version
			},
		} ) )
	}, [ dispatch, version ] )

	const value = React.useMemo( () => ({
		trackEvent,
	}), [ trackEvent ] )

	return (
		<AnalyticsContext.Provider
			value={ value }
		>
			{ children }
		</AnalyticsContext.Provider>
	)
} )
