import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'

const Container = styled.div`
	display: flex;
	flex-direction: column;
	flex-grow: 1;
	align-items: center;
	justify-content: center;
`

const Heading = styled.div`
	font-size: ${ theme.fontSize( 2 ) };
	margin: ${ theme.spacing( 0, 0, 3 ) };
`

const RetryButton = styled.button`
	display: inline-flex;
	align-items: center;
	justify-content: center;
	height: 32px;
	padding: ${ theme.spacing( 0, 1.5 ) };
	border-radius: 6px;
	background: ${ theme.colors.primary500.toString() };
	border: none;
	color: #fff;
	font-weight: 500;
	font-size: ${ theme.fontSize( 1.4 ) };
	gap: 6px;
    transition: 0.2s all ease-in-out;
	cursor: pointer;
	&:disabled {
		background: ${ theme.colors.surface05.toString() };
		color: ${ theme.colors.surface200.toString() };
		pointer-events: none;
	}
	&:hover {
		background: ${ theme.colors.primary600.toString() };
	}
	&:active {
		background: ${ theme.colors.primary700.toString() };
	}
`

export default class FunnelErrorBoundary extends React.PureComponent<{
	children: React.ReactNode,
	onRetry: () => void,
}, {
	hasError: boolean,
}> {
	// eslint-disable-next-line react/state-in-constructor
	state = { hasError: false }

	static getDerivedStateFromError() {
		return { hasError: true }
	}

	componentDidCatch( error: Error  ) {
		console.error( error )
		this.setState( { hasError: true } )
	}


	render() {
		const { children, onRetry } = this.props
		const { hasError } = this.state

		if ( hasError ) {
			return (
				<Container>
					<Heading>Failed to load the funnel.</Heading>
					<RetryButton type="button" onClick={ onRetry }>
						Try again
					</RetryButton>
				</Container>
			)
		}

		return children
	}

}