/* eslint-disable arrow-body-style */
/* eslint-disable no-unused-vars */
import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme/index'
import ReactLoader from 'components/common/reactLoading'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import Header from './components/Header/index'
import { CurrentFunnelContextProvider, FunneListContextProvider } from './contexts/index'
import { FunnelContextProvider } from './components/FunnelView/FunnelContext'
import FunnelView from './components/FunnelView/index'
import FunnelErrorBoundary from './components/FunnelView/FunnelErrorBoundary'
import FunnelSuggestions from './components/FunnelView/FunnelSuggestions/index'
import FunnelsPageLocked from './FunnelsPageLocked'
import { AnalyticsContextProvider } from './contexts/analytics'

const Container = styled.div`
	display: flex;
	flex-direction: column;
	flex-grow: 1;
	background: ${ theme.colors.primarySnow.toString() };
	min-height: 100vh;
	max-height: 100vh;
	overflow: auto;
`

const Outer = styled.div`
	display: flex;
	flex-direction: column;
	flex-grow: 1;
	min-height: 100vh;
	overflow: hidden;
`

const ContentWrapper = styled.div`
	display: flex;
	flex-direction: column;
	flex-grow: 1;
	padding: ${ theme.spacing( 2 ) };
	min-height: calc( 100% - 60px );
	z-index: 1;
`

const Content = styled.div`
	display: flex;
	flex-direction: column;
	flex-grow: 1;
	background: #fff;
	border-radius: 4px;
	padding: ${ theme.spacing( 1, 0 ) };
	max-width: 100%;
	max-height: 100%;
`

const FunnelsMain = () => {

	const rootRef = React.useRef<HTMLDivElement>() as React.MutableRefObject<HTMLDivElement>

	const [ retryFlag, setRetryFlag ] = React.useState( false )

	const retryKey = React.useMemo( () => {
		return Date.now().toString()
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [ retryFlag ] )

	const handleRetry = React.useCallback( () => {
		setRetryFlag(  ( retry ) => !retry )
	}, [] )

	const { showFunnelsPageLockScreen } = useRestrictionContext() as unknown as {
		showFunnelsPageLockScreen: boolean
	}

	if ( showFunnelsPageLockScreen ) {
	  return <FunnelsPageLocked />
	}

	return (
		<AnalyticsContextProvider version="Q2-2023">
			<React.Suspense fallback={ <ReactLoader/> }>
				<FunnelSuggestions />
				<FunnelContextProvider>
					<FunneListContextProvider>
						<CurrentFunnelContextProvider>
							<Outer ref={ rootRef }>
							<Container
								ref={ rootRef }
							>
								<Header />
								<ContentWrapper>
									<Content>
										<FunnelErrorBoundary key={ retryKey } onRetry={ handleRetry }>
											<React.Suspense fallback={ <ReactLoader/> }>
												<FunnelView
													rootRef={ rootRef }
												/>
											</React.Suspense>
										</FunnelErrorBoundary>
									</Content>
								</ContentWrapper>
							</Container>
							</Outer>
						</CurrentFunnelContextProvider>
					</FunneListContextProvider>
				</FunnelContextProvider>
			</React.Suspense>
		</AnalyticsContextProvider>
	)

}

export default React.memo( FunnelsMain )