/* eslint-disable arrow-body-style */
import React from 'react'
import styled from 'styled-components';
import { theme } from 'theme';
import FunnelSessionIcon from 'public/static/funnel/funnel-list-session.svg'
import FunnelUserIcon from 'public/static/funnel/funnel-list-user.svg'
import { UFC_Dropdown as UFCDropdown, StylesProvider, DropdownOverlay, SearchInput } from 'uxcam-frontend-components';
import { Tooltip } from 'antd';
import CirclePlusIcon from 'public/static/funnel/circlePlus.svg'
import Link from 'next/link';
import { IFunnelListItem } from '../../types'
import { useFunnelListContext } from '../../contexts';
import PinStarButton from '../PinStarButton';
import { useAnalyticsContext } from '../../contexts/analytics';
import CategorizedList from '../CategorizedDropdown/CategorizedList'
import type { CategoryGroup } from '../CategorizedDropdown/CategorizedList'
import CategorizedListRow from '../CategorizedDropdown/CategorizedListRow'
import { PinWrapper, TimeAgo } from '../CategorizedDropdown/styles'
import { getTimeAgo } from '../../utils/getTimeAgo'

const DropdownActionButton = styled.button`
	display: flex;
	justify-content: center;
	align-items: center;
	gap: 4px;
	background-color: ${ theme.colors.primary05.toString() };
	color: ${ theme.colors.primary500.toString() };
	border: none;
	height: 32px;
	width: -webkit-fill-available;
	cursor: pointer;
	font-size: 12px !important;
	border-radius: 6px;
	transition: 0.2s background-color ease-in-out;
	font-family: Roboto, sans-serif;

	svg {
		path {
			stroke: ${ theme.colors.primary500.toString() } !important;
		}
	}

	&:hover {
		background-color: ${ theme.colors.primary10.toString() };
	}

	&:disabled {
		background-color: ${ theme.colors.surface05.toString() };
		color: ${ theme.colors.surface200.toString() };
		cursor: not-allowed;
		pointer-events: none;

		svg {
			path {
				stroke: ${ theme.colors.surface200.toString() } !important;
			}
		}
	}
`

const CATEGORY_ORDER = [ 'recently_viewed', 'my_funnels', 'team_funnels' ] as const;

const CATEGORY_LABELS: Record<string, string> = {
	recently_viewed: 'Recently viewed',
	my_funnels: 'My funnels',
	team_funnels: 'Team funnels',
};

const FunnelSelector: React.FC<{
	funnels: IFunnelListItem[];
	funnelId?: string;
	onSelect: ( funnelId: string ) => void;
	disabled: boolean;
	createDisabled?: boolean;
}> = ( {
	funnelId,
	funnels,
	onSelect,
	disabled,
	createDisabled,
} ) => {

	const [ visible, setVisible ] = React.useState( false )
	const [ search, setSearch ] = React.useState( '' )
	const searchRef = React.useRef<HTMLInputElement>( null );
	const { trackEvent } = useAnalyticsContext()
	const debounceTimeout = React.useRef<ReturnType<typeof setTimeout>>()
	const debounceSearch = React.useCallback( ( newSearch: string | undefined ) => {
		// eslint-disable-next-line @typescript-eslint/no-non-null-assertion
		clearTimeout( debounceTimeout.current! )
		if ( !newSearch || newSearch.length === 0 ) {
			return;
		}
		debounceTimeout.current = setTimeout( () => {
			trackEvent( 'wa_search_report' )
		}, 2000 )
	}, [ trackEvent ] )

	const [ triggerSortRefetch, setTriggerSortRefetch ] = React.useState( false )
	const {
		pinFunnelItem,
		isPinningInFlight,
		refreshFunnelList,
		disabledMessage,
	} = useFunnelListContext()

	const handleSearch = React.useCallback( ( event: React.ChangeEvent<HTMLInputElement> ) => {
		setSearch( event.target.value )
		debounceSearch( event.target.value )
	}, [debounceSearch] )

	const handlePinClick = React.useCallback( ( funnelItemId: string, isPinned: boolean, name: string ) => {
		return ( e: React.MouseEvent ) => {
			e.stopPropagation();
			setTriggerSortRefetch( true );
			pinFunnelItem( {
				funnelId: funnelItemId,
				pin: !isPinned,
				name,
			} );
		};
	}, [ pinFunnelItem ] );

	const handleFunnelSelect = React.useCallback( ( id: string ) => {
		return () => {
			onSelect( id )
			setVisible( false )
			setTriggerSortRefetch( true )
		}
	}, [ onSelect ] )

	const categorizedItems = React.useMemo( (): CategoryGroup<IFunnelListItem>[] => {
		const searchLower = search?.toLowerCase() || '';
		const filtered = funnels.filter( ( funnel ) => funnel.name.toLowerCase().includes( searchLower ) );

		return CATEGORY_ORDER.map( ( category ) => {
			let categoryNodes = filtered.filter( ( funnel ) => funnel.categories?.includes( category ) );
			if ( category === 'recently_viewed' ) {
				categoryNodes = categoryNodes.filter( ( funnel ) => funnel.funnel_id !== funnelId ).slice( 0, 3 );
			}
			if ( category === 'my_funnels' || category === 'team_funnels' ) {
				categoryNodes = [ ...categoryNodes ].sort( ( a, b ) => {
					if ( a.is_pinned !== b.is_pinned ) return a.is_pinned ? -1 : 1
					const aTime = a.last_updated_on ? new Date( a.last_updated_on ).getTime() : 0
					const bTime = b.last_updated_on ? new Date( b.last_updated_on ).getTime() : 0
					return bTime - aTime
				} )
			}
			if ( categoryNodes.length === 0 ) return null;
			return { key: category, label: CATEGORY_LABELS[ category ], items: categoryNodes };
		} ).filter( Boolean ) as CategoryGroup<IFunnelListItem>[];
	}, [ funnels, search, funnelId ] );

	const currentFunnel = React.useMemo( () => {
		return funnels.find( ( funnel ) => {
			return funnel.funnel_id === funnelId
		} )
	}, [ funnels, funnelId ] )

	const DropdownContents = React.useMemo( () => {
		return (
			<DropdownOverlay layoutVariant="3tier" paddingVariant="vertical">
				<SearchInput ref={ searchRef } value={ search } onChange={ handleSearch } />
				<CategorizedList
					categories={ categorizedItems }
					renderItem={ ( funnel, categoryKey ) => (
						<CategorizedListRow
							key={ `${ categoryKey }-${ funnel.funnel_id }` }
							title={ funnel.name }
							isSelected={ categoryKey !== 'recently_viewed' && funnel.funnel_id === funnelId }
							onClick={ handleFunnelSelect( funnel.funnel_id ) }
							icon={ funnel.funnel_type === 'session' ? <FunnelSessionIcon /> : <FunnelUserIcon /> }
							renderActions={ ( hovered ) => (
								<>
									{ categoryKey === 'recently_viewed' ? (
										<TimeAgo>{ getTimeAgo( funnel.recently_viewed_date ) }</TimeAgo>
									) : null }
									<PinWrapper style={ { visibility: funnel.is_pinned || hovered ? 'visible' : 'hidden' } }>
										<PinStarButton
											active={ funnel.is_pinned }
											disabled={ isPinningInFlight }
											onClick={ handlePinClick( funnel.funnel_id, funnel.is_pinned, funnel.name ) }
										/>
									</PinWrapper>
								</>
							) }
						/>
					) }
				/>
				<Tooltip title={ createDisabled ? disabledMessage : undefined }>
					<span style={ { display: 'block', margin: '4px 14px 0 12px' } }>
						{ createDisabled ? (
							<DropdownActionButton disabled type="button">
								<CirclePlusIcon />
								New funnel
							</DropdownActionButton>
						) : (
							<Link href="#create">
								<DropdownActionButton type="button" onClick={ () => setVisible( false ) }>
									<CirclePlusIcon />
									New funnel
								</DropdownActionButton>
							</Link>
						) }
					</span>
				</Tooltip>
			</DropdownOverlay>
		)
	}, [ categorizedItems, funnelId, handleFunnelSelect, handlePinClick, isPinningInFlight, handleSearch, search, createDisabled, disabledMessage ] )

	return (
		<StylesProvider>
			<UFCDropdown
				trigger={ [ 'click' ] }
				overlay={ DropdownContents }
				visible={ visible }
				onVisibleChange={ (visibility) => {
					setVisible( visibility )

					if(!visibility) {
						setSearch( '' )

						if ( triggerSortRefetch ) {
							refreshFunnelList()
							setTriggerSortRefetch( false );
						}
					} else {
						refreshFunnelList()
						setTimeout( () => searchRef.current?.focus(), 10 );
					}
				} }
				destroyPopupOnHide
				disabled={ disabled }
				selectorProps={{
					selectedValue: currentFunnel?.name || 'Untitled Funnel',
					fixedWidth: 350,
				}}
			/>
		</StylesProvider>
	)
}

export default React.memo( FunnelSelector )
