import { axiosInstance } from 'services/globalInstance';
import { IFunnel, IFunnelListItem, IFunnelSuggestion } from '../types';

export const fetchFunnelList = async ( appId: string, userId: string ) => {
	  const { data } = await axiosInstance.post<{
		funneList: IFunnelListItem[], // it's a typo in the backend
		funnelLimit: number,
	  }>( `${process.env.PYTHON_API_URL_V2}/funnels/list`, {
			appid: appId,
			userid: userId,
	  }, {
		withCredentials: true,
	  } );

	  const {
		funneList,
		funnelLimit,
	  } = data

	  return {
		funnelList: funneList,
		funnelLimit,
	  }
}
export const getFetchFunnelListKey = ( appId: string ) => [ 'FUNNEL_LIST', appId ]

export const trackRecentlyViewed = async ( appId: string, userId: string, funnelId: string ) => {
	const { data } = await axiosInstance.post( `${ process.env.PYTHON_API_URL_V2 }/funnels/recently_viewed`, {
		appid: appId,
		userid: userId,
		funnel_id: funnelId,
	}, {
		withCredentials: true,
	} )
	return data
}

export const pinFunnelReport = async (
	{
		appId,
		funnelId,
		pin,
		userId,
	}: {
		appId: string,
		funnelId: string,
		pin: boolean,
		userId: string,
	}
) => {
	const { data } = await axiosInstance.post( `${process.env.PYTHON_API_URL_V2}/funnels/pin_funnel`, {
		appid: appId,
		funnel_id: funnelId,
		is_pinned: pin,
		user_id: userId,
	}, {
		withCredentials: true,
	} );

	return data
}

export const fetchFunnel = async ( funnelId: string | null, appId: string, forceUpdate = false ) => {

	if ( !funnelId ) {
		return null
	}
	const { data } = await axiosInstance.post<IFunnel>( `${process.env.PYTHON_API_URL_V2}/funnels/load`, {
		appid: appId,
		funnel_id: funnelId,
		force_update: forceUpdate,
	}, {
		withCredentials: true,
	} );

	return data
}
export const getFetchFunneKey = ( funnelId: string ) => [ 'FETCH_FUNNEL', funnelId ]

export const getSuggestionAttributeValuesKey = ( appId: string, table = '', attribute = '', value = '' ) => {
	return [ 'SUGGESTION_ATTRIBUTE_VALUES', appId, table, attribute, value ]
}

export const fetchSuggestionSearchAttribute = async ( appId: string, table = '', attribute = '', query = '' ) => {
	if ( !attribute || !table )  {
		return {
			data: [] as string[],
		}
	}

	try {
		const { data } = await axiosInstance.post<{
			data: string[],
		}>( `${process.env.PYTHON_API_URL}/search_attribute`, {
			appid: appId,
			table,
			attribute,
			dateRange: {
				from: new Date( '2022-03-14T23:00:00.000Z' ).toISOString(),
				to: new Date().toISOString(),
			},
			search: query,
			dropdownLimit: 20,
			filters: [],
		}, {
			withCredentials: true,
		} )
		return data
	} catch ( e ) {
		console.error( e )

		return {
			data: [] as string[],
		}
	}
}

export const deleteFunnel = async ( funnelId: string, appId: string ) => {
	const { data } = await axiosInstance.post( `${process.env.PYTHON_API_URL_V2}/funnels/delete`, {
		appid: appId,
		funnel_id: funnelId,
	}, {
		withCredentials: true,
	} );

	return data
}

export const getFunnelSuggestionsKey = ( appId: string, objectiveName = '' ) => [ 'FUNNEL_SUGGESTIONS', appId, objectiveName ]

export const fetchFunnelSuggestions = async ( appId: string, objectiveName = '' ) => {
	if ( !objectiveName )  {
		return {
			suggestions: [] as IFunnelSuggestion[],
		}
	}

	const { data } = await axiosInstance.post<{
		suggestions: IFunnelSuggestion[],
	}>( `${process.env.PYTHON_API_URL_V2}/insights/funnel-suggestions`, {
		appid: appId,
		last_step_value: objectiveName,
		include_step_type: [ 'screen', 'event' ],
	}, {
		withCredentials: true,
	} )

	return data

}