import React from 'react'
import { CategoryListContainer, CategorySection, EmptyMenu } from './styles'

export interface CategoryGroup<T> {
	key: string;
	label: string;
	items: T[];
}

interface CategorizedListProps<T> {
	categories: CategoryGroup<T>[];
	renderItem: ( item: T, categoryKey: string ) => React.ReactNode;
	emptyMessage?: string;
}

function CategorizedList<T>( { categories, renderItem, emptyMessage = 'No results found' }: CategorizedListProps<T> ) {
	if ( categories.length === 0 ) {
		return <EmptyMenu>{ emptyMessage }</EmptyMenu>
	}

	return (
		<CategoryListContainer>
			{ categories.map( ( { key, label, items } ) => (
				<CategorySection key={ key }>
					{ label ? <h4>{ label }</h4> : null }
					{ items.map( ( item ) => renderItem( item, key ) ) }
				</CategorySection>
			) ) }
		</CategoryListContainer>
	)
}

export default React.memo( CategorizedList ) as typeof CategorizedList
