/* eslint-disable react/jsx-no-useless-fragment */
/* eslint-disable arrow-body-style */
import React from 'react'
import styled from 'styled-components';
import { theme } from 'theme';
import { Tooltip } from 'antd';
import { useAppText } from 'Utils/helpers/commonUtils';
import { IFunnel } from '../../types'

const StepColumnInner = styled.div`
  display: block;
  font-size: ${ theme.fontSize( 1.4 ) };
  font-weight: 500;
  color: ${ theme.colors.surface300.toString() };
  gap: ${ theme.spacing( 1 ) };
  line-height: ${ theme.fontSize( 1.641 ) };
  max-width: 100%;
  word-break: initial;
`

const StepNum = styled.span`
  display: inline-block;
  margin-right: ${ theme.spacing( 0.25 ) };
`

const StepType = styled.span`
	margin: ${ theme.spacing( 0.25 ) };
`

const FadedText = styled.span`
	display: inline-block;
	color: ${ theme.colors.surface300.toString() };
	margin: ${ theme.spacing( 0, 0.25 ) };
`

const CustomStepName = styled.span`
	display: inline;
	color: ${ theme.colors.surface500.toString() };
	font-weight: 500;
`

const FilterDetails = styled.div`
	display: block;
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface300.toString() };
	font-weight: 400;
	margin-top: ${ theme.spacing( 0.25 ) };
	padding-left: ${ theme.spacing( 1.5 ) };
`

const Value = styled.span`
	display: inline-block;
	margin: 0;
	color: ${ theme.colors.surface500.toString() };
	margin: ${ theme.spacing( 0, 0.25  ) };
	word-break: break-word;
`

const OperatorOptions: {
	value: string,
	label: string;
}[] = [
	{
		label: 'equals',
		value: 'in',
	},
	{
		label: 'equals not',
		value: 'not_in',
	},
	{
		label: 'greater',
		value: 'greater',
	},
	{
		label: 'less',
		value: 'less',
	},
	{
		label: 'contains',
		value: 'contains',
	},
	{
		label: 'does not contain',
		value: 'not_contains',
	},
]

const formatSteps = ( items: string[], isScreen: boolean, renamedScreens?: Record<string, string> ) => {
	if ( !items ) return ''
	// eslint-disable-next-line no-param-reassign
	items = isScreen ? items.map( ( item ) => renamedScreens?.[ item ] || item ) : items
	if ( items?.length <= 2 ) {
		return (
			<>
				<Value>
					{items[ 0 ]}
				</Value>
				{
					items.length !== 1
					&& (
						<>
							<FadedText>or</FadedText>
							<Value>
								{items[ 1 ]}
							</Value>
						</>
					)
				}
			</>
		)
	}
	const firstItem = items?.slice( 0, 1 ).join( ', ' );
	const secondItem = items[ 1 ];
	return (
		<Value>
			{`${ firstItem }, ${ secondItem }`} <FadedText> or </FadedText> {`${ items.length - 2 } more`}
		</Value>
	);

}

const displayStepDetails = ( funnelStep: IFunnel['step_d_l'][0], renamedScreens: Record<string, string>, launchedText: string ) => {
	if ( !funnelStep.fb_l ) {
		return (
			<>
				{ launchedText }
			</>
		)
	}

	const eventCustomProperty = funnelStep?.fb_l?.[ 1 ] || null
	const values = funnelStep?.fb_l[ 0 ]?.value as string[] || []

	const getStepDetailsTitle = ( attribute: string, valueLength: number ) => {
		switch ( attribute ) {
		case 'screen_name':
			return `Screen${ valueLength > 1 ? 's' : '' }:`
		case 'nce_name':
			return `Smart event${ valueLength > 1 ? 's' : '' }:`
		default:
			return `Event${ valueLength > 1 ? 's' : '' }:`
		}
	}

	return (
		<>
			<>
				<StepType>
					{getStepDetailsTitle( funnelStep?.fb_l[ 0 ]?.attribute, values.length )}
				</StepType>
			</>
			<>
				<Tooltip title={
					// eslint-disable-next-line @typescript-eslint/no-explicit-any
					funnelStep?.fb_l[ 0 ]?.attribute === 'screen_name' ? values.map( ( item: any ) => renamedScreens[ item ] || item )?.join( ', ' ) : values.join( ', ' )
				}
				>
					{
						formatSteps( values, funnelStep?.fb_l[ 0 ]?.attribute === 'screen_name', renamedScreens )
					}
				</Tooltip>
				{
					
					eventCustomProperty
					&& (
						<>
							<FadedText>with</FadedText>
							{
								formatSteps( eventCustomProperty.json_field, false )
							}
							<FadedText>
								{ OperatorOptions.find( ( option ) => option.value === eventCustomProperty.operator )?.label }
							</FadedText>
							<Tooltip title={ Array.isArray( eventCustomProperty.value ) && eventCustomProperty.value.join( ', ' ) }>
								{
									formatSteps( Array.isArray( eventCustomProperty.value ) ? eventCustomProperty.value : [ eventCustomProperty.value ], false )
								}
							</Tooltip>
						</>
					)
				}
			</>
		</>
	)

}

const FunnelTableStep: React.FC<{
	step: IFunnel[ 'step_d_l' ][ 0 ];
	renamedScreens: Record<string, string>;
	stepNum: number;
	stepName?: string;
}> = ( {
	step,
	renamedScreens,
	stepNum,
	stepName,
} ) => {
	const { launchedText } = useAppText()
	return (
		<StepColumnInner>
			<StepNum>
				{ stepNum }.
			</StepNum>
			{ stepName ? (
				<>
					<CustomStepName>{ stepName }</CustomStepName>
					<FilterDetails>
						{ displayStepDetails( step, renamedScreens, launchedText ) }
					</FilterDetails>
				</>
			) : (
				displayStepDetails( step, renamedScreens, launchedText )
			) }
		</StepColumnInner>
	)

}

export default React.memo( FunnelTableStep )