import React from 'react'
import { useMutation, useQuery, useQueryClient } from 'react-query';
import Router, { useRouter } from 'next/router';
import { RootStateOrAny, useSelector } from 'react-redux';
import useIsLoggedInAdmin from 'hooks/useIsLoggedInAdmin';
import { IFunnel, IFunnelListItem, PinFunnelPayload } from '../types'
import { fetchFunnel, fetchFunnelList, getFetchFunneKey, getFetchFunnelListKey, pinFunnelReport, trackRecentlyViewed } from '../queries/index';
import { useAnalyticsContext } from './analytics';

interface IFunnelListContextProps {
	items: IFunnelListItem[];
	refreshFunnelList: () => Promise<unknown>;
	limitReached: boolean;
	funnelLimit: number;
	funnelsDisabled: boolean;
	disabledMessage: string;
	isViewer: boolean;
	pinFunnelItem: ( {
		funnelId,
		pin,
		name,
	}: PinFunnelPayload ) => void;
	isPinningInFlight: boolean;
}

const FunnelListContext  = React.createContext<IFunnelListContextProps>( {
	items: [],
	refreshFunnelList: () => Promise.resolve(),
	limitReached: false,
	funnelLimit: 0,
	funnelsDisabled: false,
	disabledMessage: '',
	isViewer: false,
	pinFunnelItem: () => Promise.resolve(),
	isPinningInFlight: false,
} )

interface ProviderProps {
	children: React.ReactNode;
}

export const FunneListContextProvider: React.FC<ProviderProps> = React.memo( ( { children } ) => {

	const currentOrg = useSelector(state => ( state as RootStateOrAny ).currentOrgReducer);
	const profile = useSelector( ( state ) => ( state as RootStateOrAny ).profileReducer )
	const { _id: userId } = profile
	const { isLoggedInAsAdminGuest } = useIsLoggedInAdmin()
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	const planFeature = currentOrg.planFeature as any
	const funnelFeature = planFeature?.funnelFeature
	const funnelsDisabled = !funnelFeature

	const { trackEvent } = useAnalyticsContext();

	const Router = useRouter()
	const { appId } = Router.query

	const fetchFunnelListKey = getFetchFunnelListKey( appId as string )

	const {
		data,
		refetch,
	} = useQuery( {
		queryKey: fetchFunnelListKey,
		queryFn: () => fetchFunnelList( appId as string, userId ),
		suspense: true,
	} )
	
	const queryClient = useQueryClient()

	const { mutate, isLoading } = useMutation( {
		mutationFn: (payload: PinFunnelPayload) => pinFunnelReport({
			...payload,
			appId: appId as string,
			userId,
		}),
		onMutate: async ( updatedFunnelItem ) => {
			const previousList = queryClient.getQueryData( fetchFunnelListKey )

			queryClient.setQueryData( fetchFunnelListKey, ( old: any ) => {
				if ( !old ) {
					return old
				}

				// optimistic update
				const newList = old.funnelList.map( ( item: IFunnelListItem ) => {
					if ( item.funnel_id === updatedFunnelItem.funnelId ) {
						return {
							...item,
							is_pinned: updatedFunnelItem.pin,
						}
					}
					return item
				} )

				return {
					...old,
					funnelList: newList,
				}
			})

			return { previousList, updatedFunnelItem }
		},
		onError: ( err, updatedFunnelList, context ) => {
			// rollback to previous state
			queryClient.setQueryData( fetchFunnelListKey, context?.previousList )
		}
	} )

	const limitReached = React.useMemo( () => {
		return ( data?.funnelList?.length || 0 ) >= ( data?.funnelLimit || 0 )
	}, [ data ] )

	const funnelLimit = React.useMemo( () => {
		return data?.funnelLimit || 0
	}, [ data ] )

	const appRole = React.useMemo( () => {
		const org = profile?.organization?.find( ( org: { $oid: string } ) => org.$oid === currentOrg.orgId )
		return org?.apps?.find( ( app: { id: string } ) => app.id === appId )?.role
	}, [ profile, currentOrg.orgId, appId ] )

	const isViewer = isLoggedInAsAdminGuest || appRole === 'viewer'

	const disabledMessage = React.useMemo( () => {
		if ( !funnelFeature ) {
			return 'Funnels are not available on your current plan. Please upgrade to use this feature.'
		}
		if ( limitReached ) {
			return `A maximum number of ${ funnelLimit } funnels are allowed per app. Please delete an existing funnel to create a new one.`
		}
		if ( isViewer ){
			return `You don't have permission to perform this action.`
		}
		return ''
	}, [ funnelFeature, limitReached, funnelLimit, isViewer ] )


	const refreshFunnelList = React.useCallback( () => {
		queryClient.invalidateQueries( fetchFunnelListKey )
		return refetch()
	}, [ queryClient, fetchFunnelListKey, refetch ] )

	const pinFunnelItem = React.useCallback( ( {
		funnelId,
		pin,
		name,
	}: {
		funnelId: string,
		pin: boolean,
		name?: string,
	} ) => {
		return mutate( {
			funnelId,
			pin,
		}, {
			onSuccess: (res) => {
				if ( res?.is_pinned ) {
					trackEvent( 'wa_add_feature_to_favorites', {
						feature_type: 'funnel',
						feature_name: name,
					} );
				} else {
					trackEvent( 'wa_remove_feature_from_favorites', {
						feature_type: 'funnel',
						feature_name: name,
					} );
				}
			}
		} )
	}, [mutate, trackEvent] )

	const providerValues: IFunnelListContextProps = React.useMemo( () => {
		return {
			items: data?.funnelList || [],
			funnelLimit,
			refreshFunnelList,
			limitReached,
			funnelsDisabled,
			disabledMessage,
			isViewer,
			pinFunnelItem,
			isPinningInFlight: isLoading,
		}
	}, [ data, refreshFunnelList, limitReached, funnelsDisabled, disabledMessage, funnelLimit, isViewer, pinFunnelItem, isLoading ] )

	return (
		<FunnelListContext.Provider value={ providerValues }>
			{ children }
		</FunnelListContext.Provider>
	)
} )

export const useFunnelListContext = () => {
	return React.useContext( FunnelListContext )
}


interface ICurrentFunnelContextProps {
	funnelId: string | null;
	funnel: IFunnel | null;
	loading: boolean;
	updateInProgress: boolean;
	setUpdateInProgress: ( updateInProgree: boolean ) => void;
	updateFunnelCache: ( funnel: IFunnel ) => void;
	isBuilderOpen: boolean;
	setIsBuilderOpen: ( isOpen: boolean ) => void;
	showDropOff: boolean;
	setShowDropOff: (showDropOff: boolean) => void;
}

const CurrentFunnelContext  = React.createContext<ICurrentFunnelContextProps>( {
	funnelId: null,
	funnel: null,
	loading: false,
	updateInProgress: false,
	setUpdateInProgress: () => null,
	updateFunnelCache: () => null,
	isBuilderOpen: false,
	setIsBuilderOpen: () => null,
	showDropOff: true,
	setShowDropOff: () => null,
} )

export const useCurrentFunnelContext = () => {
	return React.useContext( CurrentFunnelContext )
}

interface CurrentFunnelProviderProps {
	children: React.ReactNode;
}

const FunnelLoader: React.FC<{
	onLoading: ( isLoading: boolean ) => void;
	onFunnelLoaded: ( funnel: IFunnel ) => void;
}> = React.memo( ( {
	onLoading,
	onFunnelLoaded,
} ) => {
	const Router = useRouter()
	const { appId } = Router.query
	const { _id: userId } = useSelector( ( state ) => ( state as RootStateOrAny ).profileReducer )

	const {
		funnelId,
	} = useCurrentFunnelContext()

	const queryKey = getFetchFunneKey( funnelId as string )
	const {
		data,
		isLoading,
	} = useQuery( {
		queryKey,
		queryFn: () => fetchFunnel( funnelId as string, appId as string ),
		suspense: false,
	} )

	React.useEffect( () => {
		if ( funnelId && appId && userId ) {
			trackRecentlyViewed( appId as string, userId, funnelId as string )
		}
	}, [ funnelId, appId, userId ] )

	React.useEffect( () => {
		onLoading( isLoading )
	}, [ isLoading, onLoading ] )

	React.useEffect( () => {
		if ( data ) {
			onFunnelLoaded( data )
		}
	}, [ data, onFunnelLoaded ] )

	return null

} )

export const CurrentFunnelContextProvider: React.FC<CurrentFunnelProviderProps> = React.memo( ( { children } ) => {

	const {
		query,
	} = useRouter()

	const queryRef = React.useRef( query )

	React.useEffect( () => {
		queryRef.current = query
	}, [ query ] )

	const {
		funnelId = null,
		appId,
	} = query

	const {
		items,
	} = useFunnelListContext()

	const funnelIdsMap = React.useMemo( () => {
		const map: Record<string, boolean> = {}
		items.forEach( ( item ) => {
			map[ item.funnel_id ] = true
		} )
		return map
	}, [ items ] )

	const [ loading, setLoading ] = React.useState( false )
	const [ updateInProgress, setUpdateInProgress ] = React.useState( false )
	const [ funnelData, setFunnelData ] = React.useState<IFunnel | null>( null )
	const [ isBuilderOpen, setIsBuilderOpen ] = React.useState( false )
	const [ showDropOff, setShowDropOff ] = React.useState( true )
	const queryClient = useQueryClient()

	const updateFunnelCache = React.useCallback( ( funnel: IFunnel ) => {
		const queryKey = getFetchFunneKey( funnel.funnel_id as string )
		queryClient.setQueryData( queryKey, funnel )
	}, [ queryClient ] )

	const providerValues: ICurrentFunnelContextProps = React.useMemo( () => {
		return {
			funnel: funnelData,
			loading,
			funnelId: funnelId as string,
			updateFunnelCache,
			isBuilderOpen,
			setIsBuilderOpen,
			showDropOff,
			setShowDropOff,
			updateInProgress,
			setUpdateInProgress,
		}
	}, [funnelData, loading, funnelId, updateFunnelCache, isBuilderOpen, showDropOff, updateInProgress, setUpdateInProgress] )

	const isFunnelMissing = React.useMemo( () => {
		return funnelId && !funnelIdsMap[ funnelId as string ]
	}, [ funnelId, funnelIdsMap ] )

	// eslint-disable-next-line consistent-return
	React.useEffect( () => {
		if ( isFunnelMissing ) {
			const queryPart = ( ( queryRef.current?.url || '?' ) as string ).split( '?' )[1] || ''
			const searchParamsObj = new URLSearchParams( queryPart )
			searchParamsObj.delete( 'appId' )
			searchParamsObj.delete( 'parentType' )
			searchParamsObj.delete( 'funnelId' )
			const searchParams = searchParamsObj.toString()
	
			const isCreate = funnelId === 'create'
			const useHash = isCreate ? '#create' : ''

			if ( isCreate ) {

				if ( items.length ) {
					const useFunnelId = items[ 0 ].funnel_id
					Router.push(
						`/integration?appId=${ appId }&parentType=funnels&funnelId=${useFunnelId}${ useHash }${ searchParams ? `&${ searchParams }` : '' }`,
						`/app/${ appId }/funnels/${ useFunnelId }${ searchParams ? `?${ searchParams }` : '' }${ useHash }`
					)
	
					return
		
				}

				Router.push(
					`/integration?appId=${ appId }&parentType=funnels${ searchParams ? `&${ searchParams }` : '' }#create`,
					`/app/${ appId }/funnels${ searchParams ? `?${ searchParams }` : '' }#create`
				)

				return

			}

			if ( items.length ) {
				const useFunnelId = items[ 0 ].funnel_id
				Router.push(
					`/integration?appId=${ appId }&parentType=funnels&funnelId=${useFunnelId}`,
					`/app/${ appId }/funnels/${ useFunnelId }`
				)

				return 
	
			}

			Router.push(
				`/integration?appId=${ appId }&parentType=funnels`,
				`/app/${ appId }/funnels`
			)

			return
		}

		if ( !funnelId ) {
			if ( items.length > 0 ) {
				const useFunnelId = items[ 0 ].funnel_id
				Router.push(
					`/integration?appId=${ appId }&parentType=funnels&funnelId=${useFunnelId}`,
					`/app/${ appId }/funnels/${ useFunnelId }`
				)
			}

		}

	}, [ isFunnelMissing, items, appId, funnelId, funnelIdsMap ] )

	return (
		<CurrentFunnelContext.Provider value={ providerValues }>
			{ funnelId && !isFunnelMissing ? (
				<FunnelLoader
					onLoading={ setLoading }
					onFunnelLoaded={ setFunnelData }
				/>
			) : null }
			{ children }
		</CurrentFunnelContext.Provider>
	)

} )

