import React from 'react'
import { Tooltip } from 'antd'
import { ListItem, TitleSpan, IconWrapper } from './styles'

interface CategorizedListRowProps {
	title: string;
	isSelected: boolean;
	onClick: () => void;
	renderActions?: ( hovered: boolean ) => React.ReactNode;
	icon?: React.ReactNode;
}

const CategorizedListRow: React.FC<CategorizedListRowProps> = ( {
	title, isSelected, onClick, renderActions, icon,
} ) => {
	const [ hovered, setHovered ] = React.useState( false )
	const titleRef = React.useRef<HTMLSpanElement>( null )
	const [ isTruncated, setIsTruncated ] = React.useState( false )

	React.useEffect( () => {
		if ( titleRef.current ) {
			setIsTruncated( titleRef.current.scrollWidth > titleRef.current.clientWidth )
		}
	}, [ title ] )

	const titleElement = <TitleSpan ref={ titleRef }>{ title }</TitleSpan>

	return (
		<ListItem
			isSelected={ isSelected }
			onClick={ onClick }
			onMouseEnter={ () => setHovered( true ) }
			onMouseLeave={ () => setHovered( false ) }
		>
			{ icon ? <IconWrapper>{ icon }</IconWrapper> : null }
			{ isTruncated ? (
				<Tooltip title={ title } placement="right">
					{ titleElement }
				</Tooltip>
			) : titleElement }
			{ renderActions?.( hovered ) }
		</ListItem>
	)
}

export default React.memo( CategorizedListRow )
