import React from 'react';

import { Tooltip } from 'antd';

import StarIcon from 'public/static/funnel/star.svg';
import { PinButtonContainer } from './styles';

interface Props extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    active?: boolean;
}

const PinStarButton:React.FC<Props> = ( props ) => {
	const { active, ...rest } = props;

	return (
		// eslint-disable-next-line react/jsx-props-no-spreading
		<PinButtonContainer active={ active || false } type="button" { ...rest }>
			<Tooltip title={ active ? 'Remove from Favorites' : 'Add to Favorites' } placement="right">
				<StarIcon />
			</Tooltip>
		</PinButtonContainer>
	)
}

export default React.memo( PinStarButton );
