/* eslint-disable no-nested-ternary */
/* eslint-disable consistent-return */
/* eslint-disable arrow-body-style */
import React, { useMemo } from 'react'
import styled from 'styled-components'
import Router, { useRouter } from 'next/router'
import Funnel, { FunnelChart, useUpdateFunnelStepName } from 'dashboard-builder/dist/cjs/Funnel'
import { message } from 'antd'
import { rollbar } from 'components/common/rollbar'
import ReactLoader from 'components/common/reactLoading'
import { useLeavePageConfirmation } from 'hooks/useLeavePageConfirmation'
import { theme } from 'theme'
import MassUserIdFilter from 'components/shared/GlobalFilter/components/MassUserIdFilter'
import { useCurrentFunnelContext, useFunnelListContext } from '../../contexts/index'
import FunnelViewHead from './FunnelViewHead'
import FunnelTable from './FunnelTable'
import { IFunnel } from '../../types'
import { useAnalyticsContext } from '../../contexts/analytics'
import { extractFilterAttributes, extractStepAttributes } from '../utils'
import FunnelLanding from './FunnelLanding'
import ScrollToTop from './ScrollToTop'

const Container = styled.div`
	display: flex;
	flex-grow: 1;
	flex-direction: column;
	&[aria-busy='true'] {
		opacity: 0.72;
		pointer-events: none;
	}
`

const FunnelChartContainer = styled.div`
	display: flex;
	flex-direction: column;
	height: 100%;
	margin-bottom: 32px;
	&:empty {
		display: none;
	}
`
const BorderWrapper = styled.div`
	padding: 16px;
	border-radius: 8px;
	border: 1px solid ${ theme.colors.surface10.toString() };
	margin-bottom: 24px;
`

const EmptyContainer = styled.div`
	width: 100%;
	height: 100%;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-direction: column;
	flex: 1;
`
const TextContainer = styled.div`
`
const Top = styled.div``

const LoaderWrapper = styled.div`
	position: absolute;
	left: 0;
	right: 0;
	width: 100%;
	height: calc(100% - 60px);
	background-color: rgba(255, 255, 255, 0.8);
	display: flex;
	align-items: center;
	justify-content: center;
	flex-direction: column;
	gap: 16px;
	z-index: 10;
`

const FunnelEmptyState = ({ funnelType }:{ funnelType: 'user' | 'session' }) => (
	<EmptyContainer>
		<img src="/static/icon-happy-no-data.svg" alt='no data'/>
		<TextContainer>
			No {funnelType === 'user' ? 'users' : 'sessions'} match the first step of your funnel. Try changing the criteria.
		</TextContainer>
	</EmptyContainer>
)

const FunnelLoader = () => (
	<LoaderWrapper>
		<ReactLoader />
	</LoaderWrapper>
)

const FunnelView: React.FC<{
	rootRef: React.MutableRefObject<HTMLDivElement>,
}> = ( {
	rootRef,
} ) => {
	const { trackEvent } = useAnalyticsContext()

	const topRef = React.useRef(null)

	const {
		asPath,
		query,
	} = useRouter()

	const {
		appId,
		suggestionType,
		suggestionValue,
		url,
	} = query

	const containsPreDefinedSteps = useMemo( () => (url as string)?.split( '?' )[ 1 ], [ url ] );

	const {
		funnel,
		funnelId,
		updateFunnelCache,
		setIsBuilderOpen,
		showDropOff,
		updateInProgress,
		loading,
	} = useCurrentFunnelContext()

	const handleStepNameUpdate = React.useCallback( ( stepIndex: number, stepName: string | null ) => {
		if ( !funnel ) return
		const updatedStepDL = funnel.step_d_l.map( ( step: any, i: number ) =>
			i === stepIndex ? { ...step, name: stepName } : step
		)
		const updatedStepNames = { ...funnel.step_names }
		if ( stepName ) {
			updatedStepNames[ String( stepIndex ) ] = stepName
		} else {
			delete updatedStepNames[ String( stepIndex ) ]
		}
		updateFunnelCache( {
			...funnel,
			step_d_l: updatedStepDL,
			step_names: updatedStepNames,
		} as IFunnel )
	}, [ funnel, updateFunnelCache ] )

	const { updateStepName, stepNamesOverride, resetOverrides } = useUpdateFunnelStepName( funnel?.funnel_id ?? '', { onStepNameUpdate: handleStepNameUpdate } )
	const stepNames = React.useMemo( () => {
		return funnel?.step_d_l?.map( ( step: any, i: number ) => stepNamesOverride[ i ] ?? funnel?.step_names?.[ String( i ) ] ?? step.name ?? '' ) ?? []
	}, [ funnel?.step_d_l, funnel?.step_names, stepNamesOverride ] )

	const { contextHolder, handlePreventLeaving } = useLeavePageConfirmation();

	const nceAttributes = React.useMemo( () => {
		const attributes: { [ key: string ]: number } = {}

		// Get no code event attributes from filters
		funnel?.fb_d_l?.forEach( filter => {
			attributes[ filter.attribute ] = ( attributes[ filter.attribute ] || 0 ) + 1
		} )
		
		// Get no code event attributes from steps
		funnel?.step_d_l?.forEach( step => {
			if ( step?.table === 'no_code_event' ) {
				step?.fb_l?.forEach( fbl => {
					attributes[ fbl.attribute ] = ( attributes[ fbl.attribute ] || 0 ) + 1
				} )
			} 
		} )

		return attributes
	}, [ funnel ] )
	
	const {
		items: funnelList,
		refreshFunnelList,
		funnelLimit,
		isViewer,
	} = useFunnelListContext()
    
	React.useEffect( () => {
		if ( funnel ) {
			trackEvent( 'wa_funnels_visit_funnel', {
				id: funnel.funnel_id,
				name: funnel.name,
				filter_attributes: nceAttributes,
				favorite: funnelList?.find( ( { funnel_id: funnelid } ) => funnelid === funnel.funnel_id )?.is_pinned || false,
			} )
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [ trackEvent, funnel?.funnel_id, nceAttributes ] )

	const hash = React.useMemo( () => {
		return asPath.split( '#' )[ 1 ]
	}, [ asPath ] )

	const isEditOrCreate = React.useMemo( () => {
		if ( isViewer ) return false
		return hash === 'edit' || hash === 'create' || hash === 'clone'
	}, [ hash, isViewer ] )

	const isCreate = React.useMemo( () => {
		return hash === 'create'
	}, [ hash ] )

	const isFunnelEditReady = React.useMemo( () => {
		return hash === 'create' || ( ( hash === 'edit' || hash === 'clone' ) && funnel?.funnel_id === funnelId )
	}, [ funnelId, funnel, hash ] )

	const useSuggestions = React.useMemo( () => {
		return Boolean( suggestionType && suggestionValue )
	}, [ suggestionType, suggestionValue ] )

	React.useEffect(() => {
		if (!hash) handlePreventLeaving(false);
	}, [handlePreventLeaving, hash])

	const handleCancel = React.useCallback( () => {
		const openSuggestions = useSuggestions
		const suggesionParams = openSuggestions ? `suggestionType=${ suggestionType }&suggestionValue=${ suggestionValue }` : ''

		const useHash = openSuggestions ? `#funnel-suggestions` : ''

		if ( funnelId ) {
			Router.push(
				`/integration?appId=${ appId as string }&parentType=funnels&funnelId=${funnelId}${ suggesionParams ? `&${ suggesionParams }` : '' }${ useHash }`,
				`/app/${ appId as string }/funnels/${ funnelId }${ suggesionParams ? `?${ suggesionParams }` : '' }${ useHash }`
			)
			return
		}

		Router.push(
			`/integration?appId=${ appId as string }&parentType=funnels${ suggesionParams ? `&${ suggesionParams }` : '' }${ useHash }`,
			`/app/${ appId as string }/funnels${ suggesionParams ? `?${ suggesionParams }` : '' }${ useHash }`
		)
	}, [
		funnelId,
		appId,
		suggestionType,
		suggestionValue,
		useSuggestions,
	] )

	const handleFunnelSubmit = React.useCallback( ( funnelData: IFunnel ) => {
		resetOverrides()
		updateFunnelCache( funnelData )
		refreshFunnelList()
			.then( () => {
				setTimeout( () => {
					Router.push(
						`/integration?appId=${ appId as string }&parentType=funnels&funnelId=${ funnelData.funnel_id }`,
						`/app/${ appId as string }/funnels/${ funnelData.funnel_id }`,
					)
					.catch((e) => {
						if (!e.cancelled) {
						  throw e
						}
					  })
				}, 10 )
			} )
	}, [ updateFunnelCache, appId, refreshFunnelList, resetOverrides ] )

	const isClone = React.useMemo( () => {
		return hash === 'clone'
	}, [ hash ] )

	const handleUpdate = React.useCallback( ( funnelData: unknown ) => {
		const useFunnelData = funnelData as IFunnel
		trackEvent( 'wa_funnels_edit_funnel', {
			id: useFunnelData.funnel_id,
			type: useFunnelData.funnel_type,
			name: useFunnelData.name,
			stepsNumber: useFunnelData.step_d_l.length,
			steps: extractStepAttributes( useFunnelData ),
			order: useFunnelData.ordered_funnel ? 'this_order': 'any_order',
			conversionWindowFilter: useFunnelData.conversion_filter?.length ? useFunnelData.conversion_filter[ 0 ] : null,
			filters: extractFilterAttributes( useFunnelData ),
			grouping: useFunnelData.gb_d,
		} )
		handleFunnelSubmit( useFunnelData )
	}, [ handleFunnelSubmit, trackEvent ] )

	const handleCreate = React.useCallback( ( funnelData: unknown ) => {
		const useFunnelData = funnelData as IFunnel
		const eventName = isClone ? 'wa_funnels_clone_funnel' : 'wa_funnels_create_funnel'
		trackEvent( eventName, {
			id: useFunnelData.funnel_id,
			type: useFunnelData.funnel_type,
			name: useFunnelData.name,
			stepsNumber: useFunnelData.step_d_l.length,
			steps: extractStepAttributes( useFunnelData ),
			order: useFunnelData.ordered_funnel ? 'this_order': 'any_order',
			conversionWindowFilter: useFunnelData.conversion_filter?.length ? useFunnelData.conversion_filter[ 0 ] : null,
			filters: extractFilterAttributes( useFunnelData ),
			grouping: useFunnelData.gb_d,
		} )
		handleFunnelSubmit( useFunnelData )
	}, [ handleFunnelSubmit, trackEvent, isClone ] )

	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	const handleError = React.useCallback( ( error: any ) => {
		if ( funnelList?.length >= funnelLimit && hash === 'create' ) {
			message.error( `Funnel limit reached. A maximum number of ${ funnelLimit } funnels are allowed per app. Please delete an existing funnel to create a new one.` )
			return
		}
		message.error( error.message )
		rollbar.error( error )
	}, [ funnelList, funnelLimit, hash ] )

	const createFunnelData = React.useMemo( () => {
		if ( !isCreate ) {
			return undefined
		}
		const queryPart = ( (query.url as string || '?' ).split( '?' )[1] || '' ).split( '#' )[0]
		const searchParams = new URLSearchParams( queryPart )

		const steps = searchParams.get( 'steps' )
		const groupBy = searchParams.get( 'groupby' )
		const filters = searchParams.get( 'filters' )
		const type = searchParams.get( 'type' )

		if ( steps || groupBy || filters || type ) {

			try {
				return {
					funnel_type: type || 'session',
					ordered_funnel: true,
					step_d_l: JSON.parse( steps || '[]' ),
					gb_d: groupBy ? JSON.parse( 'gb_d' ) : null,
					fb_d_l: JSON.parse( filters || '[]' ),
					newDate: {
						From: null,
						To: null,
						relativeTo: 'NOW',
						source: 'UPLOAD_TIME',
						timezone: 'UTC',
						timezoneOffset: 0,
						unit: 'DAY',
						value: 30,
					},
				}
			} catch( e ) {
				// eslint-disable-next-line no-console
				console.error( e )
				return undefined
			}
		}

		return undefined
	}, [ query, isCreate ] )

	const useFunnelData = React.useMemo( () => {
		return hash === 'create' ? createFunnelData : funnel
	}, [ hash, funnel, createFunnelData ] )

	React.useEffect( () => {
		if ( !hash ) { return }

		switch( hash ) {
			case 'edit': {
				return trackEvent( 'wa_funnels_open_funnel_editor', {
					id: funnel?.funnel_id,
					name: funnel?.name,
				} )
			}
			case 'create': {
				return trackEvent( 'wa_funnels_open_funnel_creator' )
				
			}
			case 'clone': {
				return trackEvent( 'wa_funnels_open_funnel_clone', {
					id: funnel?.funnel_id,
					name: funnel?.name,
				} )
			}
			default: {
				return undefined
			}
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [ hash, trackEvent, funnel?.funnel_id ] )

	React.useEffect( () => {
		if ( isEditOrCreate && isFunnelEditReady ) {
			setIsBuilderOpen( true )
			return
		}
		setIsBuilderOpen( false )
	}, [ isEditOrCreate, isFunnelEditReady, setIsBuilderOpen ] )
		
	const isFunnelEmpty = React.useMemo( () => {
		return !funnel?.funnel_data?.length || Object.keys(funnel?.funnel_data?.[0]).length === 0
	}, [ funnel ] )

	const updateProgressFlag = (value: boolean) => {
		if (!containsPreDefinedSteps) {
			handlePreventLeaving(value);
		}
	}

	const handleTitleDescUpdate = React.useCallback((title: string, desc: string) => {
		if (!funnel) return;

		if (!title && !desc) return;

		const updatedFunnel = {
			...funnel,
			...(title && { name: title }),
			...(desc && { description: desc }),
		} as IFunnel;

		updateFunnelCache(updatedFunnel);
	}, [funnel, updateFunnelCache]);

	return (
		<Container aria-busy={ updateInProgress || loading }>
		    <Top id='funnel-top' ref={ topRef } />
			{contextHolder}
			{
				updateInProgress || loading && 
				<FunnelLoader />
			}
			{
				isEditOrCreate && isFunnelEditReady ? (
					<Funnel
						existingFunnels={ funnelList }
						onCreate={ handleCreate }
						onUpdate={ handleUpdate }
						onCancel={ handleCancel }
						onError={ handleError }
						isClone={ isClone }
						funnelData={ useFunnelData }
						baseElemRef={ rootRef }
						backLabel={ useSuggestions ? 'Funnel suggestions' : 'Funnel view' }
						setChangesOnPage= { updateProgressFlag }
                        initialChartData={funnel}
                        onTitleDescUpdate={ handleTitleDescUpdate }
                        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                        // @ts-ignore 
                        MassUserIdModal={ MassUserIdFilter }
					/>
				) : null
			}
			{funnel && funnelList.length ? (
				isFunnelEmpty ? (
					<BorderWrapper>
						<FunnelViewHead />
						<FunnelEmptyState funnelType={funnel?.funnel_type} />
					</BorderWrapper>
				) : (
					<>
						<BorderWrapper>
							<FunnelViewHead />
							<FunnelChartContainer>
								{funnel ? (
									<FunnelChart key={funnel.funnel_id} funnelData={funnel} showDropOff={showDropOff} stepNames={stepNames} onStepNameChange={isViewer ? undefined : updateStepName} />
								) : null}
							</FunnelChartContainer>
						</BorderWrapper>
						<FunnelTable stepNames={ stepNames } />
					</>
				)
			) : (
				!loading ? (
					<FunnelLanding />
				) : null
			) }
			<ScrollToTop scrollRef={ topRef }/>
		</Container>
	)

}

export default React.memo( FunnelView )