/* eslint-disable no-shadow */
/* eslint-disable arrow-body-style */
import React from 'react'
import styled from 'styled-components'
import { Tooltip } from 'antd'
import Router, { useRouter } from 'next/router'
import { theme } from 'theme/index'
import Link from 'next/link'
import CirclePlusIcon from 'public/static/funnel/circlePlus.svg'
import SuggestionIcon from 'public/static/funnel/suggestions-icon.svg'
import { useCurrentFunnelContext, useFunnelListContext } from '../../contexts/index'
import { IFunnelListItem } from '../../types'
import FunnelSelector from './FunnelSelector'

const Container = styled.div`
	display: flex;
	justify-content: space-between;
	position: sticky;
	top: 0;
	height: 60px;
	min-height: 60px;
	width: 100%;
	background: #fff;
	padding: ${ theme.spacing( 0, 2 ) };
	z-index: 10;
`

const Actions = styled.div`
	display: flex;
	align-items: center;
	gap: ${ theme.spacing( 1 ) };
	opacity: 1;
	visibility: visible;
	transition: 0.2s all ease-in-out;
	&[aria-hidden="true"] {
		opacity: 0;
		visibility: hidden;
	}
`

const FunnelSelectorContainer = styled.div`
	display: flex;
	align-items: center;
`

const CreateButton = styled.button`
	display: inline-flex;
	align-items: center;
	justify-content: center;
	height: 32px;
	padding: ${ theme.spacing( 0, 1.5 ) };
	border-radius: 6px;
	background: ${ theme.colors.primary500.toString() };
	border: none;
	color: #fff;
	font-weight: 500;
	font-size: ${ theme.fontSize( 1.4 ) };
	gap: 6px;
    transition: 0.2s all ease-in-out;
	cursor: pointer;
	&:disabled {
		background: ${ theme.colors.surface05.toString() };
		color: ${ theme.colors.surface200.toString() };
		pointer-events: none;
	}
	&:hover {
		background: ${ theme.colors.primary600.toString() };
	}
	&:active {
		background: ${ theme.colors.primary700.toString() };
	}
`

const SuggestionButton = styled.button`
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 6px;
	border-radius: 6px;
	height: 32px;
	font-weight: 500;
	background: ${ theme.colors.primary05.toString() };
	color: ${ theme.colors.primary500.toString() };
	padding: ${ theme.spacing( 0, 1.5 ) };
	transition: 0.2s all ease-in-out;
	border: none;
	cursor: pointer;
	&:hover {
		background: ${ theme.colors.primary100.toString() };
	}
	&:disabled {
		background: ${ theme.colors.surface05.toString() };
		color: ${ theme.colors.surface200.toString() };
		pointer-events: none;
	}
`

const StyledSuggestionsIcon = styled( SuggestionIcon )`
	transform: scale( 0.64 );
`

const FunnelsFallback: IFunnelListItem[] = [
	{
		funnel_id: 'untitled',
		name: 'Untitled funnel',
	} as unknown as IFunnelListItem,
]

const Header = () => {

	const {
		query: {
			appId,
		},
		asPath,
	} = useRouter()

	const {
		items,
		limitReached,
		disabledMessage,
		funnelsDisabled,
		isViewer,
	} = useFunnelListContext()

	const {
		funnelId,
		isBuilderOpen,
	} = useCurrentFunnelContext()

	const currentFunnel = React.useMemo( () => {
		return items.find( ( item ) => item.funnel_id === funnelId )
	}, [ items, funnelId ] )

	const handleSelectFunnel = React.useCallback( ( funnelId: string ) => {
		Router.push(
			`/integration?appId=${ appId }&parentType=funnels&funnelId=${funnelId}`,
			`/app/${ appId }/funnels/${ funnelId }`
		)
	}, [ appId ] )

	const hash = React.useMemo( () => {
		return asPath.split( '#' )[ 1 ]
	}, [ asPath ] )

	const isCreateOrClone = React.useMemo( () => {
		return hash === 'create' || hash === 'clone'
	}, [ hash ] )

	const useFunnelList = React.useMemo( () => {
		if ( ( !items.length || isCreateOrClone ) && isBuilderOpen ) return FunnelsFallback
		return items
	}, [ items, isBuilderOpen, isCreateOrClone ] )


	const useFunnelId = React.useMemo( () => {
		if ( ( !items.length || isCreateOrClone ) && isBuilderOpen ) return 'untitled'
		return currentFunnel?.funnel_id
	}, [ currentFunnel, items, isBuilderOpen, isCreateOrClone ] )

	const createDisabled = limitReached || funnelsDisabled || isViewer

	const CreateBtn = (
		<span>
			{ createDisabled ? (
				<CreateButton disabled type="button" data-intercom-target="Create funnel">
					<CirclePlusIcon />
					Create funnel
				</CreateButton>
			) : (
				<Link href="#create">
					<CreateButton type="button" data-intercom-target="Create funnel">
						<CirclePlusIcon />
						Create funnel
					</CreateButton>
				</Link>
			) }
		</span>
	)

	const SuggestionBtn = (
		<span>
			{ createDisabled ? (
				<SuggestionButton disabled type="button" data-intercom-target="Funnel suggestions button">
					<StyledSuggestionsIcon />
					Suggestions
				</SuggestionButton>
			) : (
				<Link href="#funnel-suggestions">
					<SuggestionButton type="button" data-intercom-target="Funnel suggestions button">
						<StyledSuggestionsIcon />
						Suggestions
					</SuggestionButton>
				</Link>
			) }
		</span>
	)

	return (
		<Container>
			<FunnelSelectorContainer>
				{ useFunnelId ? (
					<FunnelSelector
						disabled={ isBuilderOpen }
						createDisabled={ createDisabled }
						funnels={ useFunnelList }
						funnelId={ useFunnelId }
						onSelect={ handleSelectFunnel }
					/>
				) : null }
			</FunnelSelectorContainer>
			<Actions aria-hidden={ isBuilderOpen }>
				{ limitReached || funnelsDisabled }
				{
					createDisabled ? (
						<Tooltip title={ disabledMessage }>
							{ CreateBtn }
						</Tooltip>
					) : CreateBtn
				}
				{
					createDisabled ? (
						<Tooltip title={ disabledMessage }>
							{ SuggestionBtn }
						</Tooltip>
					) : SuggestionBtn
				}
			</Actions>
		</Container>
	)
}

export default React.memo( Header )