/* eslint-disable arrow-body-style */
import React from 'react'
import styled from 'styled-components';
import { theme } from 'theme';
import ChevronIcon from 'public/static/funnel/chevron.svg'
import { generateTableData } from './tableData';
import { dispalyPercentage, formatNumericValue } from '../utils';

const Container = styled.div`
	display: flex;
	flex-grow: 1;
	flex-direction: column;
`

const BrakdownContainer = styled.div`
	display: flex;
	width: 100%;
	flex-direction: column;
	background: rgba(243, 244, 245, 0.5);
	border-radius: 8px;
	margin-bottom: ${ theme.spacing( 2 ) };
`

const BreakdownRow = styled.div`
	display: flex;
	&[aria-hidden="true"] {
		display: none;
	}
`

const BreakdownColumn = styled.div`
	display: flex;
	min-height: 43px;
	padding: ${ theme.spacing( 1.5, 1.25 ) };
	width: calc( 100% / 6 );
`

const GroupingToggle = styled.button`
	display: inline-flex;
	background: transparent;
	border: none;
	cursor: pointer;
	height: 43px;
	font-weight: 500;
	font-size: ${ theme.fontSize( 1.4 ) };
	padding: ${ theme.spacing( 0, 1.5 ) };
	align-items: center;
	gap: ${ theme.spacing( 1 ) };
	width: auto;
	> svg {
		transform: rotate( 0deg );
		transform-origin: center;
		transition: transform 0.2s ease-in-out;
	}
	&[data-collapsed="true"] {
		> svg {
			transform: rotate( 180deg );
		}
	}
	&[aria-hidden="true"] {
		display: none;
	}
`

const ShowMoreButton = styled.button`
	display: inline-flex;
	background: transparent;
	border: none;
	cursor: pointer;
	height: 43px;
	font-weight: 400;
	color: ${ theme.colors.primary500.toString() };
	font-size: ${ theme.fontSize( 1.4 ) };
	padding: ${ theme.spacing( 0, 1.5 ) };
	align-items: center;
	gap: ${ theme.spacing( 1 ) };
	width: auto;
	> svg {
		transform: rotate( 180deg );
		transform-origin: center;
		transition: transform 0.2s ease-in-out;
	}
	&:before {
		content: 'See more';
	}
	&[data-expanded="true"] {
		&:before {
			content: 'See less';
		}
		> svg {
			transform: rotate( 0deg );
		}
	}
	&[aria-hidden="true"] {
		display: none;
	}
`

const MaxDisplayDefault = 5

const FunnelTableBreakdown: React.FC<{
	items: ReturnType<typeof generateTableData>[0]['breakdown'],
	onLinkClick: () => void;
}> = ( { items, onLinkClick } ) => {

	const [ collapsed, setCollapsed ] = React.useState( false )
	const [ expanded, setExpanded ] = React.useState( false )

	const toggleExpande = React.useCallback( () => {
		setExpanded( ( prev ) => !prev )
	}, [] )
	const toggleCollapse = React.useCallback( () => {
		setCollapsed( ( prev ) => !prev )
	}, [] )

	const maxDisplay = React.useMemo( () => {
		// eslint-disable-next-line no-nested-ternary
		return collapsed ? 0
			: expanded ? items.length : MaxDisplayDefault
	}, [collapsed, expanded, items.length] )

	const displayShowMore = React.useMemo( () => {
		return items.length > MaxDisplayDefault && !collapsed
	}, [ items, collapsed ] )

	return (
		<Container>
		<BrakdownContainer>
			<GroupingToggle onClick={ toggleCollapse } data-collapsed={ collapsed } type="button">
				Grouping
				<ChevronIcon />
			</GroupingToggle>
			{ items.map( ( {
					conversionPrevStep,
					conversionStep1,
					grouping,
					count,
					dropOffPrevStepCount,
					dropOffPrevStepPercentage,
					dropOffUrl,
					conversionUrl,
				}, i ) => {
					return (
						<BreakdownRow
							// eslint-disable-next-line react/no-array-index-key
							key={ i }
							aria-hidden={ i >= maxDisplay }
						>
							<BreakdownColumn>
								{ grouping }
							</BreakdownColumn>
							<BreakdownColumn>
								{ dispalyPercentage( conversionStep1 ) }
							</BreakdownColumn>
							<BreakdownColumn>
								{ dispalyPercentage( conversionPrevStep ) }
							</BreakdownColumn>
							<BreakdownColumn>
								{ count && conversionUrl && grouping !== 'Others' ? (
									<a onClick={ onLinkClick } target="_blank" rel="noreferrer" href={ conversionUrl }>
										{ formatNumericValue( count ) }
									</a>
								) : (
									<span>
										{ formatNumericValue( count ) }
									</span>
								) }
							</BreakdownColumn>
							<BreakdownColumn>
								{ dispalyPercentage( dropOffPrevStepPercentage ) }
							</BreakdownColumn>
							<BreakdownColumn>
								{ dropOffPrevStepCount && dropOffUrl && grouping !== 'Others' ? (
									<a onClick={ onLinkClick } target="_blank" rel="noreferrer" href={ dropOffUrl }>
										{ formatNumericValue( dropOffPrevStepCount ) }
									</a>
								) : (
									<span>
										{ formatNumericValue( dropOffPrevStepCount ) }
									</span>
								) }
							</BreakdownColumn>
						</BreakdownRow>
					)
				} ) }
				<ShowMoreButton aria-hidden={ !displayShowMore } onClick={ toggleExpande } data-expanded={ expanded } type="button">
					<ChevronIcon />
				</ShowMoreButton>
		</BrakdownContainer>
		</Container>
	)
}

export default React.memo( FunnelTableBreakdown )