/* eslint-disable arrow-body-style */
import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import { Tooltip } from 'antd'
import SuggestionsIcon from 'public/static/funnel/suggestions-icon-transparent.svg'
import Link from 'next/link'
import { useAnalyticsContext } from '../../contexts/analytics'
import { useFunnelListContext } from '../../contexts'

const Container = styled.div`
	display: flex;
	flex-grow: 1;
	align-items: center;
	color: ${ theme.colors.surface500.toString() };
`

const IllustrationContainer = styled.div`
	display: flex;
	align-items: center;
	justify-content: center;
	width: 50%;
	padding: ${ theme.spacing( 0, 2 ) };
`

const DetailsContainer = styled.div`
	display: flex;
	flex-direction: column;
	width: 50%;
	padding: ${ theme.spacing( 0, 2 ) };
`

const Illustration = styled.img`
	display: block;
	max-width: 100%;
	max-height: 100%;
	width: 500px;
`

const Heading = styled.div`
	display: block;
	margin: ${ theme.spacing( 0, 0, 0.5 ) };
	font-size: ${ theme.fontSize( 2.8 ) };
	line-height: ${ theme.fontSize( 3.5 ) };
	font-weight: 500;
`

const Heading2 = styled.div`
	display: block;
	margin: ${ theme.spacing( 0, 0, 2 ) };
	font-size: ${ theme.fontSize( 1.8 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	font-weight: 500;
`

const FeaturesList = styled.ul`
	list-style: none;
	max-width: 100%;
	width: 454px;
	margin: ${ theme.spacing( 0, 0, 2 ) };
	li {
		display: block;
		position: relative;
		font-size: ${ theme.fontSize( 1.4 ) };
		line-height: ${ theme.fontSize( 2.4 ) };
		padding-left: ${ theme.spacing( 2.25 ) };
		&:before {
			content: '';
			width: 4px;
			height: 4px;
			border-radius: 50%;
			background: ${ theme.colors.surface500.toString() };
			position: absolute;
			top: ${ theme.spacing( 1.5 ) };
			left: 0;
			transform: translateY( -50% );
		}
	}
`

const CreateButton = styled.button`
	display: inline-flex;
	align-items: center;
	justify-content: center;
	height: 32px;
	padding: ${ theme.spacing( 0, 1.5 ) };
	border-radius: 6px;
	background: transparent;
	border: none;
	color: ${ theme.colors.primary500.toString() };
	font-weight: 500;
	font-size: ${ theme.fontSize( 1.4 ) };
	gap: 6px;
    transition: 0.2s all ease-in-out;
	cursor: pointer;
	&:disabled {
		background: ${ theme.colors.surface05.toString() };
		color: ${ theme.colors.surface200.toString() };
		pointer-events: none;
	}
	&:hover {
		background: ${ theme.colors.primary05.toString() };
	}
	&:active {
		background: ${ theme.colors.primary700.toString() };
	}
`
const SuggestionBtn = styled.button`
	display: inline-flex;
	align-items: center;
	justify-content: center;
	height: 32px;
	padding: ${ theme.spacing( 0, 1.5 ) };
	border-radius: 6px;
	background: ${ theme.colors.primary500.toString() };
	border: none;
	color: #fff;
	font-weight: 500;
	font-size: ${ theme.fontSize( 1.4 ) };
	gap: 6px;
    transition: 0.2s all ease-in-out;
	cursor: pointer;
	&:disabled {
		background: ${ theme.colors.surface05.toString() };
		color: ${ theme.colors.surface200.toString() };
		pointer-events: none;
	}
	&:hover {
		background: ${ theme.colors.primary600.toString() };
	}
	&:active {
		background: ${ theme.colors.primary700.toString() };
	}
`

const Actions = styled.div`
	display: flex;
	gap: ${ theme.spacing( 4 ) };
`

const FunnelLanding = () => {

	const { trackEvent } = useAnalyticsContext()
	const { items, disabledMessage, isViewer } = useFunnelListContext()

	const handleBuildClick = React.useCallback( () => {
		trackEvent( 'wa_funnels_open_funnel_creator' )
	}, [ trackEvent ] )

	if ( items.length ) { return null }

	return (
		<Container>
			<IllustrationContainer>
				<Illustration src="/static/funnel/illustration.png" />
			</IllustrationContainer>
			<DetailsContainer>
				<Heading>Funnels</Heading>
				<Heading2>Boost your conversion rate</Heading2>
				<FeaturesList>
					<li>Track conversions and drop-offs in one view</li>
					<li>Replay the drop-offs and find out who leaves, why, and what they do instead</li>
					<li>Spot user segments that are more likely to convert</li>
				</FeaturesList>
				<Actions>
					<div>
						{ isViewer ? (
							<Tooltip title={ disabledMessage }>
								<span>
									<CreateButton type="button" disabled>
										Build funnel
									</CreateButton>
								</span>
							</Tooltip>
						) : (
							<Link href="#create">
								<CreateButton type="button" onClick={ handleBuildClick }>
									Build funnel
								</CreateButton>
							</Link>
						) }
					</div>
					<div>
						{ isViewer ? (
							<Tooltip title={ disabledMessage }>
								<span>
									<SuggestionBtn type="button" disabled>
										<SuggestionsIcon />
										Get funnel suggestions
									</SuggestionBtn>
								</span>
							</Tooltip>
						) : (
							<Link href="#funnel-suggestions">
								<SuggestionBtn type="button">
									<SuggestionsIcon />
									Get funnel suggestions
								</SuggestionBtn>
							</Link>
						) }
					</div>
				</Actions>
			</DetailsContainer>
		</Container>
	)
}

export default React.memo( FunnelLanding )