import React, { useCallback, useEffect, memo } from 'react'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import LockedPage from 'components/common/LockedPage'
import { useDispatch, useSelector } from 'react-redux'
import { trackPageViews } from 'redux/actions/trackingReport'
import Illustration from 'public/static/lock-features/funnels-locked-illustration.svg'

const FunnelsPageLocked = () => {
	const dispatch = useDispatch()
	const { setShowPricingModal } = useRestrictionContext()
	const { urlReducer: { url } } = useSelector( state => state )
	const { selfServeFlag } = useRestrictionContext()

	const handleClickSeePricing = useCallback( () => {
		setShowPricingModal( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_see_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Funnels'
			},
		} ) )
	}, [ dispatch, setShowPricingModal ] )

	const handleClickRequestPricing = useCallback( () => {
		setShowPricingModal( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_request_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Funnels'
			},
		} ) )
	}, [ dispatch, setShowPricingModal ] )

	useEffect( () => {
		dispatch( trackPageViews( null, {
			eventName: 'wa_blocked_feature_pop_up_displayed',
			track_type: 'event',
			eventProperty: {
				source: 'Funnels',
				self_Checkout: selfServeFlag,
			},
		} ) )
	}, [ url, dispatch, selfServeFlag ] )
	
	return (
		<LockedPage
			image={ Illustration }
			title="Funnels"
			subTitle="Boost your conversion rate"
			list={ 
				<>
					<li>Track conversions and drop-offs in one view.</li>
					<li>Replay the drop-offs and find out who leaves, why, <br/>and what they do instead.</li>
					<li>Spot user segments that are more likely to convert.</li>
				</>
			}
			selfServeFlag={ selfServeFlag }
			handleClickSeePricing={ handleClickSeePricing }
			handleClickRequestPricing={ handleClickRequestPricing }
		/>
	)
}

export default memo( FunnelsPageLocked )