/* eslint-disable arrow-body-style */
import { IFunnelSuggestion } from 'components/features/funnels/types'
import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import StepChevron from 'public/static/funnel/step-chevron.svg'
import ViewFunnel from 'public/static/funnel/view-funnel.svg'
import { useRouter } from 'next/router'
import { useAnalyticsContext } from 'components/features/funnels/contexts/analytics'
import { useAppText } from 'Utils/helpers/commonUtils'

const Container = styled.div`
	display: flex;
	flex-direction: column;
	width: calc( 50% - ${ theme.spacing( 1 ) } );
	border-radius: 4px;
	padding: ${ theme.spacing( 1.5, 2, 2 ) };
	border: 1px solid ${ theme.colors.surface05.toString() };
`

const Title = styled.div`
	font-size: ${ theme.fontSize( 1.2 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	font-weight: 700;
	margin: ${ theme.spacing( 0, 0, 1 ) };
`

const Steps = styled.div`
	display: flex;
	flex-wrap: wrap;
	gap: ${ theme.spacing( 1 ) };
	padding: ${ theme.spacing( 0, 0, 3.5 ) };
`

const StepItemChevronContainer = styled.div`
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 16px;
	height: 16px;
	border-radius: 50%;
	background: ${ theme.colors.surface05.toString() };
`

const StepItem = styled.div`
	display: inline-flex;
	gap: ${ theme.spacing( 1 ) };
	align-items: center;
	font-size: ${ theme.fontSize( 1.2 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	font-weight: 400;
	color: ${ theme.colors.surface400.toString() };
	&:last-of-type {
		${ StepItemChevronContainer } {
			display: none;
		}
	}
`

const Bottom = styled.div`
	display: flex;
	justify-content: flex-end;
`

const Button = styled.button`
	display: inline-flex;
	gap: ${ theme.spacing( 1 ) };
	white-space: nowrap;
	width: 130px;
	justify-content: center;
	align-items: center;
	height: 28px;
	border-radius: 6px;
	border: none;
	color: ${ theme.colors.primary500.toString() };
	background: ${ theme.colors.primary05.toString() };
	font-size: ${ theme.fontSize( 1.2 ) };
	font-weight: 500;
	cursor: pointer;
	transition: background 0.2s ease-in-out, color 0.2s ease-in-out;
	&:hover {
		background: ${ theme.colors.primary500.toString() };
		color: #fff;
	}
`

const displayStep = ( step: IFunnelSuggestion[ 'step_d_l' ][0], renamedScreens: Record<string, string>, launchedText: string ) => {
	if ( !step?.fb_l?.length ) {
		return launchedText
	}
	const value = ( step.fb_l[ 0 ].value as string )[0]
	if ( step.fb_l[ 0 ].attribute === 'screen_name' ) {
		return renamedScreens[ value ] || value
	}
	return value
}

const SuggestionItem: React.FC<{
	suggestion: IFunnelSuggestion;
	index: number;
	suggestionType: 'event_name' | 'screen_name';
	suggestionValue: string;
	renamedScreens: Record<string, string>;
}> = ( {
	index,
	suggestion,
	suggestionType,
	suggestionValue,
	renamedScreens,
} ) => {

	const Router = useRouter()
	const { appId, funnelId } = Router.query

	const { trackEvent } = useAnalyticsContext()

	const stepsUrlPart = React.useMemo( () => {

		const steps = suggestion.step_d_l.map( ( step ) => {
			return step
		} )

		return `steps=${ encodeURIComponent( JSON.stringify( steps ) ) }`
	}, [ suggestion ] )

	const handleClick = React.useCallback( () => {
		trackEvent( 'wa_funnels_view_funnel_suggestion', {
			suggestion_type: suggestionType,
			suggestion_value: suggestionValue,
		} )
		Router.push(
			`/integration?appId=${ appId }&parentType=funnels${ funnelId ? `&funnelId=${ funnelId }` : '' }&${ stepsUrlPart }&suggestionType=${ suggestionType }&suggestionValue=${ suggestionValue }#create`,
			`/app/${ appId }/funnels${ funnelId ? `/${ funnelId }` : '' }?${ stepsUrlPart }&suggestionType=${ suggestionType }&suggestionValue=${ suggestionValue }#create`,
		)
	}, [ stepsUrlPart, Router, appId, funnelId, suggestionType, suggestionValue, trackEvent ] )

	const { launchedText } = useAppText()

	return (
		<Container>
			<Title>Suggestion { index + 1 }</Title>
			<Steps>
				{
					suggestion.step_d_l.map( ( step ) => {
						return (
							<StepItem>
								{ displayStep( step, renamedScreens, launchedText ) }
								<StepItemChevronContainer>
									<StepChevron />
								</StepItemChevronContainer>
							</StepItem>
						)
					} )
				}
			</Steps>
			<Bottom>
				<Button
					type="button"
					onClick={ handleClick }
				>
					<ViewFunnel />
					View funnel
				</Button>
			</Bottom>
		</Container>
	)
}

export default React.memo( SuggestionItem )
