/* eslint-disable @typescript-eslint/no-non-null-assertion */
/* eslint-disable no-shadow */
/* eslint-disable no-unused-vars */
/* eslint-disable arrow-body-style */
import { getOldFormatLinksMap } from 'dashboard-builder/dist/cjs/Funnel'
import { IFunnel, ISessionFunnel, IUserFunnel } from "../../types";

export const generateTableData = ( funnel: IFunnel, groupingAttr: string | null ) => {
	const {
		funnel_type: funnelType,
		funnel_data: rawFunnelData,
		step_d_l: steps,
		ordered_funnel: orderedFunnel = false,
	} = funnel

	const conversionTableLinksMap = getOldFormatLinksMap( funnel )

	const useFunnelData = rawFunnelData || []

	const mappedFunnelData = funnelType === 'session'
		? ( useFunnelData as NonNullable<ISessionFunnel['funnel_data']> ).map( ( data ) => {
			const {
				step,
				session_count: count,
				session_conversion_time: conversionTime,
				session_drop_off_url: dropOffUrl,
				session_conversion_url: conversionUrl,
			} = data

			return {
				grouping: groupingAttr ? ( data as any )[ groupingAttr ] as string : null,
				step,
				count,
				conversionTime,
				dropOffUrl,
				conversionUrl,
			}
		} )
		: ( useFunnelData as NonNullable<IUserFunnel['funnel_data']> ).map( ( data ) => {
			const {
				step,
				user_count: count,
				user_conversion_time: conversionTime,
				user_drop_off_url: dropOffUrl,
				user_conversion_url: conversionUrl,
			} = data

			return {
				grouping: groupingAttr ? ( data as any )[ groupingAttr ] as string : null,
				step,
				count,
				conversionTime,
				dropOffUrl,
				conversionUrl,
			}
		} )
	
	const grouppedByStep = mappedFunnelData
		.reduce( ( acc, data ) => {
			const { step } = data
			const stepAcc = acc[ step ] || []
			stepAcc.push( data )
			acc[ step ] = stepAcc
			return acc
		}, {} as Record<string, ( typeof mappedFunnelData[0] )[]> )

	const grouppedStepWithAttribute = mappedFunnelData
		.reduce( ( acc, data ) => {
			const { step, grouping } = data
			const key = grouping ? `${ step }_${ grouping }` : step
			acc[ key ] = data
			return acc
		}, {} as Record<string, typeof mappedFunnelData[0]> )

	const groupingAttrRankings = ( grouppedByStep[ '1' ] || [] )
		.sort( ( a, b ) => b.count - a.count )
		.map( ( data ) => {
			const { grouping, step } = data
			return grouping || step
		} )
		.reduce( ( acc, grouping, i ) => {
			acc[ grouping ] = i + 1
			return acc
		}, {} as Record<string, number> )

	if ( grouppedByStep[ 'undefined' ] ) {
		return []
	}
	
	const data = new Array( steps.length )
		.fill( null )
		.map( ( _, i ) => {
			const stepNum = i + 1
			const prevStep = i
			const stepData = grouppedByStep[ stepNum ]
			const prevStepData = grouppedByStep[ prevStep ]
			const step0Data = grouppedByStep[ 1 ]

			// eslint-disable-next-line no-nested-ternary
			const step0TotalDataPoint = step0Data ? groupingAttr ? step0Data.find( ( data ) => data.grouping === '__all__' ) : step0Data[ 0 ] : null
			const totalDataPoint = groupingAttr ? stepData.find( ( data ) => data.grouping === '__all__' ) : stepData[ 0 ]
			const prevTotalDataPoint = groupingAttr && prevStepData ? prevStepData.find( ( data ) => data.grouping === '__all__' ) : prevStepData && prevStepData[ 0 ] || undefined
			// eslint-disable-next-line no-unsafe-optional-chaining
			const conversionStep1 = step0TotalDataPoint ? ( ( totalDataPoint?.count || 0 ) / step0TotalDataPoint?.count ) : 1
			// eslint-disable-next-line no-unsafe-optional-chaining
			const conversionPrevStep = prevTotalDataPoint ? ( ( totalDataPoint?.count || 0 ) / prevTotalDataPoint?.count ) : 1
			// eslint-disable-next-line no-unsafe-optional-chaining
			const totalDropOff =  prevTotalDataPoint ? ( ( prevTotalDataPoint?.count ) - ( totalDataPoint?.count || 0 ) ) : 0
			const totalDropOffPercentage = prevTotalDataPoint ? 1 - ( totalDataPoint?.count || 0 ) / ( prevTotalDataPoint?.count || 0 ) : 0

			let {
				dropOffUrl,
				conversionUrl,
			} = totalDataPoint || {}

			if ( !orderedFunnel ) {
				const isGroupped = Boolean( groupingAttr )
				const oldLinkKey = isGroupped ? `${ stepNum }_all` : `${ stepNum }_count`
				const urls = conversionTableLinksMap[ oldLinkKey ] || {}
				conversionUrl = urls.completionUrl || ''
				dropOffUrl = urls.dropOffUrl || ''
			}

			return {
				step: stepNum,
				conversionStep1,
				conversionPrevStep,
				count: totalDataPoint?.count || 0,
				dropOffPrevStepCount: totalDropOff,
				dropOffPrevStepPercentage: totalDropOffPercentage,
				dropOffUrl: dropOffUrl || null,
				conversionUrl: conversionUrl || null,
				breakdown: stepData
					.filter( ( data ) => !groupingAttr || data.grouping !== '__all__' )
					.sort( ( a, b ) => {
						const aRank = groupingAttrRankings[ a.grouping || a.step ]
						const bRank = groupingAttrRankings[ b.grouping || b.step ]
						return aRank - bRank
					} )
					.map( ( data ) => {
						const { grouping } = data
						let { conversionUrl, dropOffUrl } = data
						const prevKey = grouping ? `${ prevStep }_${ grouping }` : prevStep
						const step1Key = grouping ? `1_${ grouping }` : '1'

						if ( !orderedFunnel ) {
							const oldLinkKey = grouping ? `${ stepNum }_${ grouping }` : `${ stepNum }_count`
							const urls = conversionTableLinksMap[ oldLinkKey ] || {}
							conversionUrl = urls.completionUrl || ''
							dropOffUrl = urls.dropOffUrl || ''
						}


						const prevStepData = grouppedStepWithAttribute[ prevKey ]
						// eslint-disable-next-line @typescript-eslint/no-non-null-assertion
						const step1Data = grouppedStepWithAttribute[ step1Key ]!
						const { count } = data

						const conversionStep1 = count / step1Data.count
						const conversionPrevStep = prevStepData ? ( count / prevStepData.count )
							: 1
						const dropOffPrevStepCount = prevStepData === undefined ? 0 : prevStepData.count - count
						const dropOffPrevStepPercentage = prevStepData === undefined ? 0 : 1 - (count / prevStepData.count )
						
						return {
							grouping,
							conversionStep1,
							conversionPrevStep,
							count,
							dropOffPrevStepCount,
							dropOffPrevStepPercentage,
							conversionUrl,
							dropOffUrl,
						}
					} ),
			}
			
		} )

	return data
}