import React from 'react'
// eslint-disable-next-line import/no-extraneous-dependencies
import { FunnelContext } from 'dashboard-builder/dist/cjs/Funnel'
// eslint-disable-next-line import/no-extraneous-dependencies
import { fetchPlanHatApi } from 'redux/actions/common';
import { useDispatch } from 'react-redux';
import { useRouter } from 'next/router';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { useIsAppType } from 'hooks/useIsAppType';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { tokenRefreshManager } from 'services/tokenRefreshManager';

const env = process.env.APP_ENV || 'develop';
const useEnv = env === 'local' ? 'local' : env;

export const FunnelContextProvider: React.FC<{
	children: React.ReactNode,
}> = React.memo( ( { children } ) => {

	const dispatch = useDispatch();
	const {
		query: {
			appId,
			parentType,
		},
	} = useRouter()

	const trackEvent = React.useCallback(
		(eventName: string, property: unknown) => {
		dispatch(trackPageViews(null, {
			eventName,
			track_type: 'event',
			eventProperty: property,
			pageName: parentType,
		}))
		dispatch(
			fetchPlanHatApi({
				action: eventName,
				property,
			})
		);
		},
		[dispatch, parentType]
	);

	const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
	const isWebSDK = useIsAppType( 'web' );
	const newScreenFilter = useFeatureFlag('new-screens-filter')
	const { retentionFeatureAllowed } = useRestrictionContext() as unknown as { retentionFeatureAllowed: boolean };
	const { aiSessionFeatureAllowed: aiSessionsEnabled } = useRestrictionContext() as unknown as { aiSessionFeatureAllowed: boolean } || {};

	return (
		<FunnelContext trackEvent={ trackEvent } appId={ appId } env={ useEnv } cohortsEnabled={ retentionFeatureAllowed } noCodeEnabled={ noCodeEventsFeatureFlag } isWebSDK={ isWebSDK } newScreenFilter={ newScreenFilter }  isNewAISessionEnabled={aiSessionsEnabled} onBeforeRequest={ tokenRefreshManager.refreshIfNeeded }>
			{ children }
		</FunnelContext>
	)
} )
